diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..82299dc
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,51 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { app, fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+
+test("cooking bechamel takes earliest-expiring milk (HD-1022) before newer milk (HD-1026)", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(res.status, 200);
+  const milkUsed = res.body.used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed, { itemId: 2, batches: [{ batchId: 4, qty: 2 }] });
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+});
+
+test("cooking bechamel drains HD-1022 first and takes the remainder from HD-1026", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 15 } });
+  assert.equal(res.status, 200);
+  const milkUsed = res.body.used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed, {
+    itemId: 2,
+    batches: [
+      { batchId: 4, qty: 2 },
+      { batchId: 3, qty: 1 },
+    ],
+  });
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 7);
+});
+
+test("consume orders batches by expiry, with null expiry last, then receivedOn, then id", () => {
+  const store = fresh();
+  store.data.batches = store.data.batches.filter((b) => b.itemId !== 4);
+  store.data.batches.push(
+    { id: 16, itemId: 4, lot: "NO-EXP-LATE-B", qty: 1, receivedOn: "2026-10-05", expires: null, location: "dry" },
+    { id: 14, itemId: 4, lot: "NO-EXP-EARLY", qty: 1, receivedOn: "2026-10-01", expires: null, location: "dry" },
+    { id: 15, itemId: 4, lot: "NO-EXP-LATE-A", qty: 1, receivedOn: "2026-10-05", expires: null, location: "dry" },
+    { id: 13, itemId: 4, lot: "EXP-LATER", qty: 1, receivedOn: "2026-10-20", expires: "2026-11-10", location: "dry" },
+    { id: 12, itemId: 4, lot: "EXP-SOON-RECV-LATE", qty: 1, receivedOn: "2026-10-22", expires: "2026-11-05", location: "dry" },
+    { id: 11, itemId: 4, lot: "EXP-SOON-RECV-EARLY-B", qty: 1, receivedOn: "2026-10-19", expires: "2026-11-05", location: "dry" },
+    { id: 10, itemId: 4, lot: "EXP-SOON-RECV-EARLY-A", qty: 1, receivedOn: "2026-10-19", expires: "2026-11-05", location: "dry" },
+  );
+  const used = consume(store, 4, 7, { at, ref: "fefo" });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [10, 11, 12, 13, 14, 15, 16],
+  );
+});
